				"name": "Counter.cls",
				"text": "VERSION 1.0 CLASS\nBEGIN\n  MultiUse = -1  'True\nEND\nAttribute VB_Name = \"Counter\"\nOption Explicit\nPrivate mCount As Integer\nPrivate mTotal As Integer\nPrivate mLimit As Integer\n\nPublic Sub Reset()\n  mCount = 0\n  mTotal = 0\nEnd Sub\n\nPublic Sub Add(ByVal v As Integer)\n  mCount = mCount + 1\n  mTotal = mTotal + v\nEnd Sub\n\nPublic Property Get Count() As Integer\n  Count = mCount\nEnd Property\n\nPublic Property Get Total() As Integer\n  Total = mTotal\nEnd Property\n\nPublic Property Let Limit(ByVal v As Integer)\n  mLimit = v\nEnd Property\n\nPublic Property Get Limit() As Integer\n  Limit = mLimit\nEnd Property\n\nPublic Function Describe(ByVal s As String) As String\n  Describe = s & \"=\" & mTotal\nEnd Function\n"
